examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space4) {
    MonarchStepper(steps, current: connected == nil ? 0 : 1, compact: .automatic)
    if let host = connected {
        MonarchDomainProgress(host, stage: stage, isRechecking: false)
        Text("DNS records")
            .monarchTextStyle(.subheading)
            .accessibilityAddTraits(.isHeader)
        Text("Add these records where the DNS for your domain is managed.")
            .monarchTextStyle(.body)
            .foregroundStyle(theme.colors.textMuted)
        MonarchDnsRecordTable(
            [
                MonarchDnsRecord(type: "CNAME", name: host, value: "pages.example.net", purpose: .routing, isFound: stage != .dns),
                MonarchDnsRecord(type: "TXT", name: "_verify.\(host)", value: "verify=4f1c9a2e7b", purpose: .verification, isFound: stage != .dns),
            ],
            layout: .cards
        )
        MonarchButton("Verify DNS", variant: .primary, fullWidth: true) {
            stage = stage == .dns ? .certificate : .live
        }
        .disabled(stage == .live)
        MonarchButton("Remove domain", variant: .danger, fullWidth: true) { isConfirmingRemoval = true }
            .confirmationDialog("Remove \(host)?", isPresented: $isConfirmingRemoval, titleVisibility: .visible) {
                Button("Remove domain", role: .destructive) {
                    connected = nil
                    stage = .dns
                }
            } message: {
                Text("The domain stops working here. You can connect it again later.")
            }
    } else {
        HStack(alignment: .top, spacing: theme.spacing.space2) {
            MonarchTextField(
                {{field.label}},
                text: $domain,
                prompt: {{field.placeholder}},
                helper: {{field.description}},
                error: domainError,
                isRequired: true
            )
            .autocorrectionDisabled()
            MonarchButton({{connect}}, variant: .primary) {
                guard !domain.isEmpty, domainError == nil else { return }
                connected = domain.trimmingCharacters(in: .whitespaces).lowercased()
            }
            .padding(.top, theme.spacing.space6)
        }
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var domain = ""
@State private var connected: String?
@State private var stage = MonarchDomainStage.dns
@State private var isConfirmingRemoval = false
private let steps = [
    MonarchStepperStep(id: "domain", label: {{steps.0}}),
    MonarchStepperStep(id: "dns", label: {{steps.1}}),
    MonarchStepperStep(id: "verify", label: {{steps.2}}),
    MonarchStepperStep(id: "live", label: {{steps.3}}),
]

private var domainError: String? {
    let host = domain.trimmingCharacters(in: .whitespaces).lowercased()
    guard !host.isEmpty else { return nil }
    let isHost = host.contains(".") && !host.contains("/") && !host.contains(":") && !host.contains(" ")
    return isHost ? nil : "Enter a domain such as help.example.com, without https:// or a path."
}

